const JAMB_SYLLABUS_GUIDANCE: Record<string, string> = { Mathematics: "SS2/SS3 algebra, functions, trigonometry, coordinate geometry, sequences and series, statistics, probability, differentiation, integration, vectors, and financial mathematics", Physics: "SS2/SS3 measurements, mechanics, motion, forces, energy, heat, waves, optics, electricity, magnetism, atomic physics, and practical applications", Chemistry: "SS2/SS3 atomic structure, periodic table, chemical bonding, mole concept, stoichiometry, acids and bases, organic chemistry, equilibrium, electrochemistry, and environmental chemistry", Biology: "SS2/SS3 cell biology, nutrition, transport, respiration, excretion, coordination, reproduction, genetics, evolution, ecology, and practical biology", "Use of English": "SS2/SS3 reading comprehension, lexis and structure, grammar, vocabulary, idioms, sentence completion, registers, oral English, and summary skills", "Literature in English": "SS2/SS3 drama, prose, poetry, literary devices, plot, characterisation, theme, setting, tone, and prescribed-text analysis" };

const scoreSchema = z.object({
  studentId: z.number().int().positive(), session: z.string().min(1), term: z.string().min(1), className: z.string().min(1), subject: z.string().min(1), firstCa: z.number().int().min(0).optional(), secondCa: z.number().int().min(0).optional(), thirdCa: z.number().int().min(0).optional(), caScore: z.number().int().min(0), examScore: z.number().int().min(0),
}).superRefine((input, ctx) => {
  const limits = getScoreLimits(input.className);
  const components = [input.firstCa ?? 0, input.secondCa ?? 0, input.thirdCa ?? 0];
  components.forEach((score, index) => { if (score > limits.caEach) ctx.addIssue({ code: z.ZodIssueCode.too_big, origin: "number", maximum: limits.caEach, inclusive: true, path: [["firstCa", "secondCa", "thirdCa"][index]], message: `CA score cannot exceed ${limits.caEach}` }); });
  const total = components.reduce((sum, score) => sum + score, 0);
  if (input.examScore > limits.exam) ctx.addIssue({ code: z.ZodIssueCode.too_big, origin: "number", maximum: limits.exam, inclusive: true, path: ["examScore"], message: `Exam score cannot exceed ${limits.exam}` });
  if (total > limits.caEach * 3 || total !== input.caScore) ctx.addIssue({ code: z.ZodIssueCode.custom, path: ["caScore"], message: `CA components must add up to ${limits.caEach * 3} or less and match caScore` });
});


const SUBJECT_TERMINOLOGY_OVERRIDES: Array<{ match: RegExp; arabicName: string }> = [
  { match: /^qur['’]?an(?: studies)?$/i, arabicName: "القرآن الكريم" },
  { match: /^islamic studies$/i, arabicName: "الدراسات الإسلامية" },
  { match: /^islamic religious studies$/i, arabicName: "التربية الإسلامية" },
  { match: /^civic education$/i, arabicName: "التربية المدنية" },
  { match: /^basic science$/i, arabicName: "العلوم الأساسية" },
  { match: /^basic technology$/i, arabicName: "التكنولوجيا الأساسية" },
  { match: /^social studies$/i, arabicName: "الدراسات الاجتماعية" },
  { match: /^christian religious studies$/i, arabicName: "التربية الدينية المسيحية" },
];

async function translateSubjectName(name: string) {
  const override = SUBJECT_TERMINOLOGY_OVERRIDES.find(item => item.match.test(name.trim()));
  if (override) return { arabicName: override.arabicName, confidence: 1, reviewRequired: false, source: "school-override" as const };
  const response = await invokeLLM({
    model: "gpt-5-mini",
    messages: [
      { role: "system", content: "You translate school subject names from English to Modern Standard Arabic. Use the school terminology context when applicable. Return only JSON matching the requested schema. Confidence must reflect translation certainty from 0 to 1; mark reviewRequired true when the name is ambiguous, a proper noun, or needs human confirmation." },
      { role: "user", content: "Translate this school subject name to Arabic: " + name },
    ],
    maxTokens: 160,
    responseFormat: { type: "json_schema", json_schema: { name: "arabic_subject_translation", strict: true, schema: { type: "object", properties: { arabicName: { type: "string" }, confidence: { type: "number", minimum: 0, maximum: 1 }, reviewRequired: { type: "boolean" } }, required: ["arabicName", "confidence", "reviewRequired"], additionalProperties: false } } },
  });
  const content = response.choices[0]?.message?.content;
  const raw = Array.isArray(content)
    ? content.filter(part => part.type === "text").map(part => part.text).join("\n").trim()
    : typeof content === "string"
      ? content.trim()
      : "";
  try {
    const parsed = JSON.parse(raw) as { arabicName?: unknown; confidence?: unknown; reviewRequired?: unknown };
    const arabicName = String(parsed.arabicName ?? "").trim();
    const confidence = Number(parsed.confidence);
    const reviewRequired = Boolean(parsed.reviewRequired) || confidence < 0.85;
    if (arabicName.length < 2 || !/[\u0600-\u06FF]/.test(arabicName) || !Number.isFinite(confidence) || confidence < 0 || confidence > 1) throw new Error("invalid translation");
    return { arabicName, confidence, reviewRequired, source: "ai" as const };
  } catch {
    throw new TRPCError({ code: "INTERNAL_SERVER_ERROR", message: "The translation service returned an invalid Arabic subject response" });
  }
}

function linkedStudentIdOrThrow(user: { role: string; linkedStudentId?: number | null; mustChangePassword?: boolean }) {
  if (user.role === "student" && user.mustChangePassword) throw new TRPCError({ code: "FORBIDDEN", message: "Change your default password before accessing student records" });
  if ((user.role === "parent" || user.role === "student") && !user.linkedStudentId) {
    throw new TRPCError({ code: "FORBIDDEN", message: "Link this portal account to a student before accessing family records" });
  }
  return user.linkedStudentId ?? undefined;
}

